begin;
select extensions.no_plan();

insert into auth.users (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at) values ('a7010000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','writer@p207.example.test','',statement_timestamp(),'{}','{}',statement_timestamp(),statement_timestamp());
insert into public.organizations (id, legal_name, business_name, slug) values ('a7020000-0000-0000-0000-000000000001','P207 Synthetic Inc.','P207 Synthetic','p207-synthetic'),('a7020000-0000-0000-0000-000000000002','P207 Foreign Inc.','P207 Foreign','p207-foreign');
insert into public.branches (id,organization_id,name,slug,code,address_line1,city,province) values ('a7030000-0000-0000-0000-000000000001','a7020000-0000-0000-0000-000000000001','P207','p207','P207','1 Test','Test','Test'),('a7030000-0000-0000-0000-000000000002','a7020000-0000-0000-0000-000000000002','Foreign','p207f','P207F','1 Test','Test','Test');
insert into public.organization_members (id,organization_id,user_id,membership_status,joined_at) values ('a7040000-0000-0000-0000-000000000001','a7020000-0000-0000-0000-000000000001','a7010000-0000-0000-0000-000000000001','active',statement_timestamp());
insert into public.branch_memberships (organization_id,organization_member_id,branch_id) values ('a7020000-0000-0000-0000-000000000001','a7040000-0000-0000-0000-000000000001','a7030000-0000-0000-0000-000000000001');
insert into public.member_roles (organization_id,organization_member_id,role_id,branch_id,assigned_by) select 'a7020000-0000-0000-0000-000000000001','a7040000-0000-0000-0000-000000000001',id,'a7030000-0000-0000-0000-000000000001','a7010000-0000-0000-0000-000000000001' from public.roles where organization_id is null and code = 'DENTIST';
insert into public.patients (id,organization_id,patient_number,first_name,last_name,birth_date) values ('a7050000-0000-0000-0000-000000000001','a7020000-0000-0000-0000-000000000001','P-000001','Ana','Patient',date '1990-01-01'),('a7050000-0000-0000-0000-000000000002','a7020000-0000-0000-0000-000000000001','P-000002','Bea','Patient',date '1991-01-01'),('a7050000-0000-0000-0000-000000000003','a7020000-0000-0000-0000-000000000002','P-000001','Foreign','Patient',date '1992-01-01');
select extensions.ok(has_function_privilege('authenticated','public.create_patient_contact(uuid,uuid,text,text,text,boolean,boolean)','EXECUTE') and not has_function_privilege('service_role','public.create_patient_contact(uuid,uuid,text,text,text,boolean,boolean)','EXECUTE'),'only authenticated receives child RPC grants');
grant select on public.patient_contacts to authenticated;
set local role authenticated; select set_config('request.jwt.claim.role','authenticated',true); select set_config('request.jwt.claim.sub','a7010000-0000-0000-0000-000000000001',true);
select extensions.is((select version from public.create_patient_contact('a7030000-0000-0000-0000-000000000001','a7050000-0000-0000-0000-000000000001','MOBILE','Mobile','09171234567',true,false)),1,'contact create normalizes through the authoritative generated column');
select extensions.throws_ok($$select public.create_patient_contact('a7030000-0000-0000-0000-000000000001','a7050000-0000-0000-0000-000000000002','MOBILE',null,'09171234567',true,false)$$,'P0001','duplicate review required','mobile duplicate requires confirmation');
select extensions.is((select version from public.create_patient_contact('a7030000-0000-0000-0000-000000000001','a7050000-0000-0000-0000-000000000002','MOBILE',null,'09171234567',true,true)),1,'confirmed mobile duplicate commits');
select extensions.is((select version from public.create_patient_relationship('a7030000-0000-0000-0000-000000000001','a7050000-0000-0000-0000-000000000001',null,'External Guardian','09171234567',null,'GUARDIAN',true,false,false)),1,'external guardian relationship is created');
select extensions.throws_ok($$select public.create_patient_relationship('a7030000-0000-0000-0000-000000000001','a7050000-0000-0000-0000-000000000001','a7050000-0000-0000-0000-000000000003',null,null,null,'GUARDIAN',true,false,false)$$,'22023','invalid input','foreign related patient is rejected safely');
select extensions.is((select version from public.archive_patient_contact('a7030000-0000-0000-0000-000000000001',(select id from public.patient_contacts where patient_id='a7050000-0000-0000-0000-000000000001'),'a7050000-0000-0000-0000-000000000001',1)),2,'contact archive increments its version');
select extensions.throws_ok($$select public.archive_patient_contact('a7030000-0000-0000-0000-000000000001',(select id from public.patient_contacts where patient_id='a7050000-0000-0000-0000-000000000001'),'a7050000-0000-0000-0000-000000000001',1)$$,'P0001','invalid state','archived contact is read-only');
reset role;
revoke select on public.patient_contacts from authenticated;
select extensions.is((select count(*)::integer from public.audit_events where patient_id='a7050000-0000-0000-0000-000000000001' and action like 'patient.%'),3,'each successful child mutation appends one opaque patient audit');
with test_failures as (select finish from extensions.finish() where finish !~ '^1\.\.[0-9]+$') select case when count(*)=0 then 'P1_TEST_PASS' else 'P1_TEST_FAIL' end as p1_test_result from test_failures;
rollback;
